import assert from 'node:assert/strict';
import { ARENA_ENEMIES } from '../src/js/toy-room/ArenaEnemies.js';
import { selectArenaEnemyAttack, updateArenaEnemyAI } from '../src/js/toy-room/ArenaEnemyAI.js';

function makeBattle(actor, behavior, distance = 250) {
  const enemy = {
    actor, x: 800, state: 'APPROACH', elapsed: 0, attackIndex: 0,
    lastAIChoice: null, hp: ARENA_ENEMIES[actor].hp
  };
  const state = {
    enemy, playerBehavior: { samples: 180, jumping: 0, attacking: 0, distant: 0 },
    jump: 0, attackTime: 0, crouching: false
  };
  Object.assign(state.playerBehavior, behavior);
  return {
    state,
    room: { player: { x: enemy.x - distance }, story: { state: { attackDirection: 1 } } },
    presentation: { enemies: ARENA_ENEMIES },
    tuning: { left: 160, right: 1440 },
    getEnemyCollisionDistance: () => 150,
    setEnemyState(next) { enemy.state = next; enemy.elapsed = 0; },
    beginEnemyAttack(attack) { enemy.attack = attack; enemy.state = 'ATTACK'; }
  };
}

const robotAtRange = makeBattle('robot', { distant: 1 });
assert.equal(
  selectArenaEnemyAttack(robotAtRange, 500, ['Laser Beam', 'Rocket Punch']),
  'Laser Beam',
  'A distância recorrente favorece o golpe de maior alcance'
);

const robotAgainstAggression = makeBattle('robot', { attacking: 1 });
assert.equal(
  selectArenaEnemyAttack(robotAgainstAggression, 200, ['Laser Beam', 'Rocket Punch']),
  'Rocket Punch',
  'Ataques frequentes da jogadora favorecem a resposta mais incisiva do robô'
);

const dinosaurAgainstJumps = makeBattle('dinosaur', { jumping: 1 });
assert.equal(
  selectArenaEnemyAttack(dinosaurAgainstJumps, 200, ['Bite', 'Rush']),
  'Rush',
  'Saltos frequentes favorecem a investida do dinossauro'
);

const bearAgainstJumps = makeBattle('bear', { jumping: 1 });
assert.equal(
  selectArenaEnemyAttack(bearAgainstJumps, 200, ['Bear Hug', 'Belly Charge', 'Toy Leap']),
  'Toy Leap',
  'Saltos frequentes favorecem o salto do urso'
);

const bearAtRange = makeBattle('bear', { distant: 1 });
assert.equal(
  selectArenaEnemyAttack(bearAtRange, 500, ['Bear Hug', 'Belly Charge', 'Toy Leap']),
  'Belly Charge',
  'Distância recorrente favorece o golpe de avanço do urso'
);

const bearRepeating = makeBattle('bear', { jumping: 0.5, distant: 0.5 });
bearRepeating.state.enemy.lastAIChoice = 'Toy Leap';
assert.equal(
  selectArenaEnemyAttack(bearRepeating, 200, ['Bear Hug', 'Belly Charge', 'Toy Leap']),
  'Belly Charge',
  'A memória de escolhas reduz a repetição do mesmo golpe'
);

const train = makeBattle('train', { distant: 1 });
assert.equal(
  selectArenaEnemyAttack(train, 500, ['Steam Blast', 'Front Charge']),
  null,
  'O trem introdutório conserva sua sequência previsível'
);

const observation = makeBattle('robot', {}, 500);
observation.state.enemy.state = 'ATTACK';
observation.state.jump = 90;
observation.state.attackTime = 12;
for (let frame = 0; frame < 30; frame++) updateArenaEnemyAI(observation, 1);
assert.ok(observation.state.playerBehavior.jumping > 0.1);
assert.ok(observation.state.playerBehavior.attacking > 0.1);
assert.ok(observation.state.playerBehavior.distant > 0.1);
const restored = JSON.parse(JSON.stringify(observation.state));
assert.deepEqual(restored.playerBehavior, observation.state.playerBehavior, 'O perfil observado sobrevive ao snapshot');

console.log('APROVADO: seleção adaptativa por distância, saltos, ataques frequentes e variedade; trem preservado; memória serializável.');
